import java.util.Scanner;

public class Main {
    static long inf = 17446744073709551616L;
    static long[][] dp_array = new long[18][250005];
    static long[] factorials = new long[250005];
    static long[] inv_factorials = new long[250005];
    static long mod_value;
    static long total_n, total_k;

    static long fast_power(long base, long exp) {
        long result = 1L;
        while (exp > 0) {
            if ((exp & 1L) == 1L) result = (result * base) % mod_value;
            base = (base * base) % mod_value;
            exp >>= 1;
        }
        return result;
    }

    static long nCr(int a, int b) {
        return (((factorials[a] * inv_factorials[b]) % mod_value) * inv_factorials[a - b]) % mod_value;
    }

    static long compute() {
        int i, j, l;
        factorials[0] = 1L;
        for (i = 1; i <= total_n; i++) {
            factorials[i] = (factorials[i - 1] * i) % mod_value;
        }
        inv_factorials[total_n] = fast_power(factorials[total_n], mod_value - 2);
        for (i = total_n - 1; i >= 0; i--) {
            inv_factorials[i] = (inv_factorials[i + 1] * (i + 1)) % mod_value;
        }
        for (i = 1; i <= total_n; i++) {
            dp_array[1][i] = inv_factorials[i];
        }
        long answer = (dp_array[1][(int) total_n] * nCr((int) total_k, 1)) % mod_value;
        int t = (int) Math.min(17, total_k);
        for (i = 2; i <= t; i++) {
            for (j = (int) total_n; j > 0; j = (j - 1) & (int) total_n) {
                for (l = j; l > 0; l = (l - 1) & j) {
                    dp_array[i][j] += dp_array[i - 1][j ^ l] * inv_factorials[l];
                    if (dp_array[i][j] > inf) dp_array[i][j] %= mod_value;
                }
                dp_array[i][j] %= mod_value;
            }
            answer += dp_array[i][(int) total_n] * nCr(total_k, i);
            answer %= mod_value;
        }
        answer = (answer * factorials[(int) total_n]) % mod_value;
        return answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_n = sc.nextLong();
        total_k = sc.nextLong();
        mod_value = sc.nextLong();

        long ans = fast_power(total_k, total_n);
        if ((total_n & 1) == 1) {
            System.out.println(ans);
        } else {
            ans = (ans - compute() + mod_value) % mod_value;
            System.out.println(ans);
        }
        sc.close();
    }
}
